package app.gymsupreme.core.session

import app.gymsupreme.core.journal.Journal
import app.gymsupreme.core.journal.SnapshotSchema
import app.gymsupreme.core.json.Json
import app.gymsupreme.core.json.JsonWriter
import java.io.File
import kotlin.test.Test
import kotlin.test.assertEquals
import kotlin.test.assertIs
import kotlin.test.assertTrue

/**
 * 0.3 L1: the Kotlin lock-screen reducer must write exactly the bytes the Dart transitions write.
 * The vectors are generated by packages/gym_engine/tool/gen_contract_fixtures.dart from
 * Session.done / retarget / skipRest; CI keeps the two fixture directories identical.
 */
@Suppress("UNCHECKED_CAST")
class LockReducerTest {
    private val dir = File("src/test/fixtures/contract")
    private val uuid = "3f2b8c1e-4a5d-4e6f-9a7b-1c2d3e4f5a6b"

    private fun vectors(): List<Map<String, Any?>> =
        dir.listFiles { f -> f.name.startsWith("lockscreen_v1_") }.orEmpty().sortedBy { it.name }
            .map { Json.parseObject(it.readText(Charsets.UTF_8).trimEnd('\n')) }

    private fun fixture(name: String): Map<String, Any?> =
        Json.parseObject(File(dir, "snapshot_v1_$name.json").readText(Charsets.UTF_8).trimEnd('\n'))

    private fun applied(r: LockReducer.Result): Map<String, Any?> = assertIs<LockReducer.Result.Applied>(r).snapshot

    @Test
    fun `every vector replays byte for byte, step by step`() {
        val vs = vectors()
        assertTrue(vs.size >= 10, "expected the lock-screen vectors, found ${vs.size}")
        for (v in vs) {
            val name = v["case"] as String
            var s = v["before"] as Map<String, Any?>
            val steps = v["steps"] as List<Map<String, Any?>>
            val after = v["after"] as List<Map<String, Any?>>
            assertEquals(steps.size, after.size, name)
            for ((i, step) in steps.withIndex()) {
                val action = LockReducer.Action.of(step["action"] as String) ?: error("$name: unknown action")
                val out = applied(LockReducer.apply(s, action, step["set_id"] as String?, step["now_ms"] as Long))
                assertEquals(JsonWriter.write(after[i]), JsonWriter.write(out), "$name step $i (${action.wire})")
                // The output is what the journal accepts: a valid line at rev + 1.
                SnapshotSchema.validate(Json.parseObject(JsonWriter.write(out)))
                assertEquals((s["rev"] as Long) + 1, out["rev"], "$name step $i rev")
                s = out
            }
        }
    }

    @Test
    fun `the input snapshot is never mutated`() {
        val before = fixture("resting")
        val bytes = JsonWriter.write(before)
        LockReducer.apply(before, LockReducer.Action.DONE, "$uuid:2", 1795400270000)
        LockReducer.apply(before, LockReducer.Action.PLUS_REP, "$uuid:2", 1795400270000)
        LockReducer.apply(before, LockReducer.Action.SKIP_REST, null, 1795400270000)
        assertEquals(bytes, JsonWriter.write(before))
    }

    @Test
    fun `a second Done on the same set is a no-op (double tap at the reducer)`() {
        val once = applied(LockReducer.apply(fixture("resting"), LockReducer.Action.DONE, "$uuid:2", 1795400270000))
        assertEquals(LockReducer.Result.NoOp("not_pending"), LockReducer.apply(once, LockReducer.Action.DONE, "$uuid:2", 1795400271000))
    }

    @Test
    fun `Kotlin-only refusals`() {
        val now = 1795400270000
        assertEquals(LockReducer.Result.NoOp("paused"), LockReducer.apply(fixture("paused"), LockReducer.Action.DONE, "$uuid:2", now))
        assertEquals(LockReducer.Result.NoOp("finished"), LockReducer.apply(fixture("finished"), LockReducer.Action.DONE, "$uuid:4", now))
        assertEquals(LockReducer.Result.NoOp("unknown_set"), LockReducer.apply(fixture("resting"), LockReducer.Action.DONE, "$uuid:99", now))
        assertEquals(LockReducer.Result.NoOp("unknown_set"), LockReducer.apply(fixture("resting"), LockReducer.Action.DONE, null, now))
        assertEquals(LockReducer.Result.NoOp("not_pending"), LockReducer.apply(fixture("resting"), LockReducer.Action.PLUS_REP, "$uuid:0", now))
        // The pushdown is a stack lift with no planned weight: "Set starting weight in the app".
        assertEquals(LockReducer.Result.NoOp("not_eligible"), LockReducer.apply(fixture("resting"), LockReducer.Action.DONE, "$uuid:3", now))
        assertEquals(LockReducer.Result.NoOp("not_eligible"), LockReducer.apply(fixture("resting"), LockReducer.Action.PLUS_REP, "$uuid:3", now))
        assertEquals(LockReducer.Result.NoOp("no_rest"), LockReducer.apply(fixture("mid_set"), LockReducer.Action.SKIP_REST, null, now))
        // resting: the rest from set :1 ends at t0 + 380 s.
        assertEquals(LockReducer.Result.NoOp("rest_over"), LockReducer.apply(fixture("resting"), LockReducer.Action.SKIP_REST, null, 1795400380000))
        assertIs<LockReducer.Result.Applied>(LockReducer.apply(fixture("resting"), LockReducer.Action.SKIP_REST, null, 1795400379999))
    }

    @Test
    fun `timed sets and sets with a block get no Done or +1`() {
        val s = fixture("fresh")
        val ex = (s["exercises"] as List<Map<String, Any?>>)[0]
        val set = (ex["sets"] as List<Map<String, Any?>>)[0]
        assertTrue(LockReducer.eligible(ex, set))
        assertEquals(false, LockReducer.eligible(ex, LinkedHashMap(set).also { it["kind"] = "timed" }))
        assertEquals(false, LockReducer.eligible(ex, LinkedHashMap(set).also { it["block"] = linkedMapOf<String, Any?>("type" to "emom") }))
        assertEquals(false, LockReducer.eligible(ex, LinkedHashMap(set).also { it["target_reps"] = null }))
        assertEquals(false, LockReducer.eligible(LinkedHashMap(ex).also { it["load_kind"] = "machine" }, LinkedHashMap(set).also { it["target_load_g"] = null }))
        val bodyweight = LinkedHashMap(ex).also { it["load_kind"] = "bodyweight" }
        assertTrue(LockReducer.eligible(bodyweight, LinkedHashMap(set).also { it["target_load_g"] = null }))
    }

    @Test
    fun `a Done result is accepted by the journal as the next rev`() {
        val before = fixture("resting")
        val head = Journal.head(before)
        val out = JsonWriter.write(applied(LockReducer.apply(before, LockReducer.Action.DONE, "$uuid:2", 1795400270000)))
        assertIs<Journal.Submit.Accepted>(Journal.submit(out, head.rev, head, isStart = false))
    }
}
